    {
        //_args.ca

        //info(tableId2Name(comm.TableId));

        switch(_args.parmEnum())
        {
            case METItemsStatus::New :
                info("New");
            break;

            case METItemsStatus::Active :
                info("Active");
            break;

            case METItemsStatus::Discontinued :
                info("Discontinued");
            break;

            case METItemsStatus::Deleted :
                info("Deleted");
            break;

            case METItemsStatus::PackChange :
                info("PackChange");
            break;
        }
    }
}

public void manualUpdateToNew()
{
    try
    {
        if(metInventItemOrderSetup && metInventItemOrderSetup.ItemStatus == METConstants::Active)
        {
            this.updateStatusToNew(metInventItemOrderSetup);
            METInventItemOrderSetup::updateChildItemSiteStatusToNew(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId);
        }
        //this.itemStatusToTransferDependSites();METReqItemTableInventDimView
